<?php require 'functions.php'; $items=load_data('products');
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$items=array_filter($items,fn($x)=>(int)$x['id']!==$id);save_data('products',$items);redirect('products.php','Produto excluído.');}
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0); $row=['id'=>$id?:next_id($items),'name'=>trim($_POST['name']),'sku'=>trim($_POST['sku']),'weight'=>(float)$_POST['weight'],'value'=>(float)$_POST['value']]; if($id){foreach($items as &$x){if((int)$x['id']===$id){$x=$row;break;}}}else{$items[]=$row;} save_data('products',$items);redirect('products.php',$id?'Produto atualizado.':'Produto cadastrado.'); }
$edit=isset($_GET['edit'])?find_by_id($items,(int)$_GET['edit']):null; $title='Produtos';require 'header.php';?>
<h2 class="page-title">Produtos</h2><div class="row g-4"><div class="col-lg-4"><div class="card p-4"><h5><?=$edit?'Editar':'Novo'?> produto</h5><form method="post"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><label class="form-label">Nome</label><input required class="form-control mb-2" name="name" value="<?=h($edit['name']??'')?>"><label class="form-label">Código/SKU</label><input required class="form-control mb-2" name="sku" value="<?=h($edit['sku']??'')?>"><label class="form-label">Peso (kg)</label><input required type="number" step="0.01" class="form-control mb-2" name="weight" value="<?=h($edit['weight']??'')?>"><label class="form-label">Valor (R$)</label><input required type="number" step="0.01" class="form-control mb-3" name="value" value="<?=h($edit['value']??'')?>"><button class="btn btn-primary w-100">Salvar</button></form></div></div><div class="col-lg-8"><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Produto</th><th>SKU</th><th>Peso</th><th>Ações</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=$x['id']?></td><td><?=h($x['name'])?></td><td><?=h($x['sku'])?></td><td><?=number_format($x['weight'],2,',','.')?> kg</td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$x['id']?>">Editar</a> <a onclick="return confirm('Excluir?')" class="btn btn-sm btn-outline-danger" href="?delete=<?=$x['id']?>">Excluir</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require 'footer.php';?>
